# Action Popup

- Activating an action entry point opens the popup for the action `id` and selected context.
- The popup is resizable, with its resize handle placed for the popup position.
- The popup shows the action label, description, execution status, phase-specific log, and previous runs.
- Agent actions show run-specific prompt input and agent, model, and thinking-level selection.
- `onBefore` and `onAfter` actions are shown as links. Activating a link opens the related action by `id` with the same context.
- `Run` asks the Electron-side action runner to start the action.
- While the action is running, `Cancel` asks Electron to stop the active process and chain.
- `Schedule` opens the scheduling flow defined in `design\feature_descriptions\ready\F_022_scheduled_actions.md`.
- When custom input was entered, `Convert to action` creates a reusable action definition.
- The built-in `custom prompt` action is always available in supported contexts.

import ArrowUpwardOutlined from '@mui/icons-material/ArrowUpwardOutlined'
import CheckOutlined from '@mui/icons-material/CheckOutlined'
import StopOutlined from '@mui/icons-material/StopOutlined'
import { Box, Button, IconButton, Tooltip } from '@mui/material'
import CalendarOutline from 'mdi-material-ui/CalendarOutline'
import Play from 'mdi-material-ui/Play'
import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import { useActionRunSelector } from '../hooks/use_action_runs'
import type { ActionConversationStore } from './action_conversation_store'
import type { ActionHistoryStore } from './action_history_store'
import {
    cancelPopupAction,
    convertPromptToAction,
    currentActionPromptDraft,
    finishPopupAction,
    runPopupAction,
    saveAndRunPopupAction,
} from './action_popup_operations'
import { actionPopupRunDisabled } from './action_popup_run_disabled'
import type { ActionRunInputStore } from './action_run_input_store'
import type { ActionRunResultStore } from './action_run_result_store'
import type { ActionScheduleStore } from './action_schedule_store'
import { ActionUsageSummaryOwner } from './action_usage_summary_owner'
import { useActionRunSettings } from './use_action_run_settings'

interface ActionPopupBottomRowProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    scheduleStore: ActionScheduleStore
    showSaveControls: boolean
}

/** Run controls; subscribes only to run and prompt values used by this row. */
export function ActionPopupBottomRow(props: ActionPopupBottomRowProps) {
    const {
        action, assignmentContext, conversationStore, historyStore, inputStore, resultStore,
        runValidationError, scheduleStore, showSaveControls,
    } = props
    const settings = useActionRunSettings(action, inputStore)
    const runStatus = useActionRunSelector(action.id, assignmentContext, (run) => run?.status ?? 'idle')
    const agentActive = useActionRunSelector(action.id, assignmentContext, (run) => {
        const active = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'

        return !!active && run?.activeActionType === 'agent'
    })
    const interactionReady = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.interactionReady)
    const manualFinishAvailable = useActionRunSelector(
        action.id,
        assignmentContext,
        (run) => run?.activeActionType === 'agent' && !!run.activeActionStreaming && !run.activeActionAutoFinish,
    )
    const hasApprovals = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.approvals.length)
    const hasQuestion = useActionRunSelector(action.id, assignmentContext, (run) => !!run?.question)
    const promptDraft = currentActionPromptDraft(action, assignmentContext, action.type === 'agent')
    const prompt = useSyncExternalStore(promptDraft.subscribe, promptDraft.getSnapshot, promptDraft.getSnapshot)
    const editorSnapshot = useSyncExternalStore(
        promptDraft.subscribeEditor,
        promptDraft.getEditorSnapshot,
        promptDraft.getEditorSnapshot,
    )
    const sessionActive = runStatus === 'queued' || runStatus === 'running' || runStatus === 'waitingForInput'
    const showAgentSend = sessionActive ? agentActive : action.type === 'agent'
    const showCommandRun = !sessionActive && action.type === 'command'
    const saveDisabled = settings.actionLabel.trim().length === 0 || sessionActive || !!settings.runDisabledMessage
    const runState = {
        agentActive,
        hasApprovals,
        hasQuestion,
        interactionReady,
        runDisabledMessage: settings.runDisabledMessage,
        runStatus,
        saveDisabled,
    }
    const runDisabled = actionPopupRunDisabled(
        action,
        runState,
        prompt,
        editorSnapshot.preparationStatus,
        showSaveControls,
    )
    const operationInput = {
        action,
        context: assignmentContext,
        conversationStore,
        historyStore,
        inputStore,
        resultStore,
        runValidationError,
        settings,
    }

    const handlePrimaryRun = async () => {
        if (showSaveControls) await saveAndRunPopupAction(operationInput)
        else await runPopupAction(operationInput)
    }
    const handleSave = async () => {
        await convertPromptToAction(operationInput)
    }
    const handleCancel = () => void cancelPopupAction(action, assignmentContext)
    const handleFinish = () => void finishPopupAction(action, assignmentContext)
    const handleToggleSchedule = () => scheduleStore.toggle()

    return (
        <Box sx={{ alignItems: 'center', bgcolor: 'background.default', borderTop: 1, borderColor: 'divider', display: 'flex', gap: 1, px: 2, py: 1.5 }}>
            <ActionUsageSummaryOwner
                action={action}
                context={assignmentContext}
                conversationStore={conversationStore}
                historyStore={historyStore}
            />
            <Box sx={{ flex: 1 }} />
            {sessionActive ? (
                <Tooltip title="Stop">
                    <span>
                        <IconButton aria-label="Stop" disabled={!settings.backendAvailable} onClick={handleCancel} size="small">
                            <StopOutlined sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : null}
            {manualFinishAvailable ? (
                <Tooltip title="Finish">
                    <span>
                        <IconButton
                            aria-label="Finish"
                            disabled={!settings.backendAvailable || !interactionReady}
                            onClick={handleFinish}
                            size="small"
                        >
                            <CheckOutlined sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : null}
            {showSaveControls ? (
                <Button disabled={saveDisabled} onClick={handleSave} size="small" variant="outlined">Save</Button>
            ) : null}
            <Button
                disabled={sessionActive || !settings.backendAvailable}
                onClick={handleToggleSchedule}
                size="small"
                startIcon={<CalendarOutline sx={{ fontSize: '14px !important' }} />}
                sx={{
                    bgcolor: 'background.paper',
                    borderColor: 'divider',
                    color: 'text.secondary',
                    height: 34,
                    '&:hover': { borderColor: 'primary.main', color: 'primary.main' },
                }}
                variant="outlined"
            >
                Schedule
            </Button>
            {showAgentSend ? (
                <Tooltip title="Send">
                    <span>
                        <IconButton aria-label="Send" color="primary" disabled={runDisabled} onClick={handlePrimaryRun} size="small">
                            <ArrowUpwardOutlined sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : showCommandRun ? (
                <Button
                    disabled={runDisabled}
                    onClick={handlePrimaryRun}
                    size="small"
                    startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                    sx={{ height: 34, px: 2 }}
                    variant="contained"
                >
                    Run
                </Button>
            ) : null}
        </Box>
    )
}

import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import type { ThinkingLevel } from '../../data/agent_profiles'
import { actionPromptDraftService } from '../../services/actions/action_prompt_draft_service'
import { actionRunRegistry } from '../../services/actions/action_run_registry'
import { dialogService } from '../../services/dialog_service'
import {
    defaultCancelAction,
    defaultConvertPromptToAction,
    defaultFinishAction,
    defaultRunAction,
} from './action_popup_defaults'
import type { ActionConversationStore } from './action_conversation_store'
import type { ActionHistoryStore } from './action_history_store'
import type { ActionRunInputStore } from './action_run_input_store'
import type { ActionRunResultStore } from './action_run_result_store'

const DEFAULT_CONVERT_LABEL_LENGTH = 40

export interface ResolvedActionRunSettings {
    accessLevel: string
    agent: string
    approvalPolicy: string
    model: string
    thinkingLevel: ThinkingLevel
}

export interface ActionPopupOperationInput {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    settings: ResolvedActionRunSettings
}

export function currentActionRun(action: ActionDefinition, context: ActionContext) {
    return actionRunRegistry.getActionRunStore(action.id, context)?.getSnapshot() ?? null
}

export function currentActionPromptDraft(action: ActionDefinition, context: ActionContext, prepare: boolean) {
    const run = currentActionRun(action, context)

    return actionPromptDraftService.getDraft(action.id, context, run, { prepare })
}

async function runWithPrompt(input: ActionPopupOperationInput, prompt: string) {
    const { action, context, conversationStore, historyStore, resultStore, runValidationError, settings } = input
    resultStore.setRunning()
    try {
        if (runValidationError) throw new Error(runValidationError)

        const liveConversation = currentActionRun(action, context)?.conversation ?? null
        const continuationPath = conversationStore.continuationPath(liveConversation)
        const runInput = action.type === 'agent'
            ? {
                ...(settings.accessLevel ? { accessLevel: settings.accessLevel } : {}),
                ...(settings.agent ? { agent: settings.agent } : {}),
                ...(settings.approvalPolicy ? { approvalPolicy: settings.approvalPolicy } : {}),
                ...(continuationPath ? { continueFrom: continuationPath } : {}),
                prompt,
                ...(settings.model ? { model: settings.model } : {}),
                thinkingLevel: settings.thinkingLevel,
            }
            : { extraPrompt: prompt }
        const handleStarted = (runId: string) => {
            resultStore.setRunId(runId)
            actionPromptDraftService.clearDraft(action.id, context, currentActionRun(action, context))
        }
        const result = await defaultRunAction(action, context, runInput, handleStarted)
        resultStore.setResult(result)
        await historyStore.load()
        if (action.type === 'agent') await conversationStore.load()
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Action run failed'
        resultStore.setResult({
            logs: [{
                actionId: action.id,
                actionName: action.label,
                command: null,
                message,
                phase: 'main',
                status: 'failed',
                stderr: message,
                stdout: '',
            }],
            status: 'failed',
        })
        dialogService.error(error, { fallbackMessage: 'Action run failed' })
    }
}

export async function runPopupAction(input: ActionPopupOperationInput) {
    const { action, context } = input
    const run = currentActionRun(action, context)
    const promptDraft = actionPromptDraftService.getDraft(action.id, context, run, { prepare: false })
    const prompt = promptDraft.getSnapshot()
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    const agentActive = sessionActive && run?.activeActionType === 'agent'

    if (agentActive && run) {
        if (run.question || run.approvals.length) return
        try {
            if (run.activeActionStreaming) await promptDraft.send()
            else {
                await promptDraft.synchronize()
                actionPromptDraftService.clearDraft(action.id, context, run)
            }
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not send agent message' })
        }
        return
    }

    await runWithPrompt(input, prompt)
}

export async function convertPromptToAction(input: ActionPopupOperationInput) {
    const { action, context, inputStore, settings } = input
    const prompt = currentActionPromptDraft(action, context, false).getSnapshot()
    const { actionLabel } = inputStore.getSnapshot()
    inputStore.setConvertMessage(null)
    try {
        const label = actionLabel.trim().length > 0 ? actionLabel : prompt.trim().slice(0, DEFAULT_CONVERT_LABEL_LENGTH)
        const convertInput = {
            ...(settings.accessLevel ? { accessLevel: settings.accessLevel } : {}),
            ...(settings.agent ? { agent: settings.agent } : {}),
            ...(settings.approvalPolicy ? { approvalPolicy: settings.approvalPolicy } : {}),
            context,
            label,
            ...(settings.model ? { model: settings.model } : {}),
            prompt,
        }
        const result = await defaultConvertPromptToAction(convertInput)
        inputStore.setConvertMessage(`Saved ${result.path}`)

        return true
    } catch (error) {
        inputStore.setConvertMessage(error instanceof Error ? error.message : 'Could not convert prompt to action')

        return false
    }
}

export async function saveAndRunPopupAction(input: ActionPopupOperationInput) {
    if (!await convertPromptToAction(input)) return

    await runPopupAction(input)
}

export async function cancelPopupAction(action: ActionDefinition, context: ActionContext) {
    const run = currentActionRun(action, context)
    if (!run) return

    await defaultCancelAction(run.runId)
    actionPromptDraftService.clearDraft(action.id, context, run)
}

export async function finishPopupAction(action: ActionDefinition, context: ActionContext) {
    const run = currentActionRun(action, context)
    if (!run) return

    try {
        await defaultFinishAction(run.runId)
        actionPromptDraftService.clearDraft(action.id, context, run)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Could not finish agent session' })
    }
}

import type { ActionContext } from '../../data/action_context'
import type { AgentConversation } from '../../data/data_types'
import { actionPromptDraftService } from '../../services/actions/action_prompt_draft_service'
import { actionRunRegistry } from '../../services/actions/action_run_registry'
import { dialogService } from '../../services/dialog_service'
import type { ConversationPickerConversation } from './action_conversation_picker_data'
import { defaultLoadConversation, defaultLoadConversations } from './action_popup_defaults'

interface ActionConversationSnapshot {
    conversations: AgentConversation[]
    loading: boolean
    selectedConversation: AgentConversation | null
}

type Listener = () => void

function belongsToContext(conversation: ConversationPickerConversation, context: ActionContext) {
    return context.kind === 'project'
        ? conversation.cardInternalId === null
        : conversation.cardInternalId === context.cardInternalId
}

function conversationTimestamp(conversation: ConversationPickerConversation) {
    const timestamp = Date.parse(conversation.startedAt)

    return Number.isNaN(timestamp) ? 0 : timestamp
}

export function conversationOptions<T extends ConversationPickerConversation>(
    conversations: T[],
    actionId: string,
    context: ActionContext,
    liveConversation: T | null,
) {
    const byId = new Map<string, T>()
    for (const conversation of conversations) {
        if (belongsToContext(conversation, context) && conversation.actionId === actionId) {
            byId.set(conversation.id, conversation)
        }
    }
    if (liveConversation && belongsToContext(liveConversation, context) && liveConversation.actionId === actionId) {
        byId.set(liveConversation.id, liveConversation)
    }

    return [...byId.values()].sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))
}

function latestWaitingConversation(conversations: AgentConversation[], actionId: string, context: ActionContext) {
    return conversations
        .filter((conversation) => belongsToContext(conversation, context)
            && conversation.actionId === actionId
            && conversation.status === 'waitingForInput')
        .sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))[0] ?? null
}

/** Owns history loading and selection for one popup action/context binding. */
export class ActionConversationStore {
    private readonly actionId: string
    private readonly context: ActionContext
    private initialSelectionConfigured = false
    private initialSelectionPath: string | null = null
    private loadRequest = 0
    private readonly listeners = new Set<Listener>()
    private snapshot: ActionConversationSnapshot = { conversations: [], loading: true, selectedConversation: null }

    constructor(actionId: string, context: ActionContext) {
        this.actionId = actionId
        this.context = context
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: Listener) => {
        this.listeners.add(listener)

        return () => this.listeners.delete(listener)
    }

    /** Sets one automatic selection consumed by initial history load. */
    configureInitialSelection(path: string | null) {
        if (this.initialSelectionConfigured) return

        this.initialSelectionConfigured = true
        this.initialSelectionPath = path
    }

    async load() {
        const request = this.loadRequest + 1
        this.loadRequest = request
        this.setSnapshot({ ...this.snapshot, loading: true })
        try {
            const conversations = await defaultLoadConversations(this.context)
            if (request !== this.loadRequest) return

            const run = actionRunRegistry.getActionRunStore(this.actionId, this.context)?.getSnapshot() ?? null
            const runActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
            let selectedConversation = runActive
                ? this.snapshot.selectedConversation
                : this.snapshot.selectedConversation ?? latestWaitingConversation(conversations, this.actionId, this.context)
            const initialSelectionPath = this.initialSelectionPath
            this.initialSelectionPath = null
            if (!runActive && !selectedConversation && initialSelectionPath) {
                try {
                    const loadedConversation = await defaultLoadConversation(initialSelectionPath)
                    if (request !== this.loadRequest) return
                    this.validateSelection(loadedConversation)
                    selectedConversation = loadedConversation
                } catch (error) {
                    if (request !== this.loadRequest) return

                    this.setSnapshot({ conversations, loading: false, selectedConversation: null })
                    dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })
                    return
                }
            }
            this.setSnapshot({ conversations, loading: false, selectedConversation })
            if (selectedConversation?.status === 'waitingForInput') {
                actionPromptDraftService.clearDraft(this.actionId, this.context, null)
            }
        } catch (error) {
            if (request !== this.loadRequest) return

            this.setSnapshot({ conversations: [], loading: false, selectedConversation: null })
            dialogService.error(error, { fallbackMessage: 'Could not load agent conversations' })
        }
    }

    async select(path: string) {
        const request = this.loadRequest + 1
        this.loadRequest = request
        if (!path) {
            this.setSnapshot({ ...this.snapshot, selectedConversation: null })
            this.clearPromptDraft()
            return
        }

        try {
            const conversation = await defaultLoadConversation(path)
            if (request !== this.loadRequest) return
            this.validateSelection(conversation)

            this.setSnapshot({ ...this.snapshot, selectedConversation: conversation })
            this.clearPromptDraft()
        } catch (error) {
            if (request === this.loadRequest) {
                dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })
            }
        }
    }

    conversationOptions(liveConversation: AgentConversation | null): AgentConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null): ConversationPickerConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null) {
        const selected = this.snapshot.selectedConversation
        const conversations = selected ? [...this.snapshot.conversations, selected] : this.snapshot.conversations

        return conversationOptions(conversations, this.actionId, this.context, liveConversation)
    }

    continuationPath(liveConversation: AgentConversation | null) {
        return liveConversation?.path ?? this.snapshot.selectedConversation?.path ?? null
    }

    private clearPromptDraft() {
        const run = actionRunRegistry.getActionRunStore(this.actionId, this.context)?.getSnapshot() ?? null
        actionPromptDraftService.clearDraft(this.actionId, this.context, run)
    }

    private validateSelection(conversation: AgentConversation) {
        if (!belongsToContext(conversation, this.context)) throw new Error('Selected agent conversation belongs to another context')
        if (conversation.actionId !== this.actionId) throw new Error('Selected agent conversation belongs to another action')
    }

    private setSnapshot(snapshot: ActionConversationSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

